package dev.netlab.media;
import dev.netlab.*;
import dev.netlab.core.*;
import dev.netlab.media.core.*;
import net.minecraft.commands.Commands;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.event.RegisterCommandsEvent;
import java.util.*;
/** Explicit operator command; validates the whole footprint before writing blocks. */
public final class MediaDemo {
    public static void register(RegisterCommandsEvent e){e.getDispatcher().register(Commands.literal("netlab").then(Commands.literal("media").requires(s->s.hasPermission(2)).then(Commands.literal("kit").executes(c->{var p=c.getSource().getPlayerOrException();Media.DEVICES.values().forEach(b->give(p,new ItemStack(b.get())));Media.MODULES.values().forEach(i->give(p,new ItemStack(i.get())));Media.CABLES.values().forEach(i->give(p,new ItemStack(i.get())));give(p,new ItemStack(Media.PHONE_SIP.get()));give(p,new ItemStack(NetLab.GUIDE.get()));give(p,new ItemStack(NetLab.PORTABLE_TERMINAL.get()));give(p,new ItemStack(NetLab.MEMORY_CARD.get(),8));return 1;}))));
        e.getDispatcher().register(Commands.literal("netlab").then(Commands.literal("demo").requires(s->s.hasPermission(2)).then(Commands.literal("media").executes(c->{var p=c.getSource().getPlayerOrException();var level=p.serverLevel();var base=p.blockPosition().offset(-5,0,4);for(int x=0;x<12;x++)for(int z=0;z<8;z++)for(int y=-1;y<3;y++){var pos=base.offset(x,y,z);if(!level.hasChunkAt(pos)||level.isOutsideBuildHeight(pos)||!level.getWorldBorder().isWithinBounds(pos)||y>=0&&!level.isEmptyBlock(pos)||y<0&&!level.isEmptyBlock(pos)&&!level.getBlockState(pos).isFaceSturdy(level,pos,Direction.UP)){c.getSource().sendFailure(Component.literal("Освободи ровную область 12×8×3 к югу. Ничего не изменено."));return 0;}}
            int subnet=50;var occupied=new HashSet<String>();for(var host:DeviceEntity.loaded(level))for(var device:Arrays.asList(host.device,host.upperDevice))if(device!=null)for(var port:device.ports)occupied.add(port.ip);while(subnet<250){final int n=subnet;if(occupied.stream().noneMatch(ip->ip.startsWith("192.168."+n+".")))break;subnet++;}if(subnet==250)return 0;String lan="192.168."+subnet+".";for(int x=0;x<12;x++)for(int z=0;z<8;z++)if(level.isEmptyBlock(base.offset(x,-1,z)))level.setBlockAndUpdate(base.offset(x,-1,z),Blocks.SMOOTH_STONE.defaultBlockState());
            var rack=place(level,base.offset(1,0,1),NetLab.RACK.get());rack.device=device(MediaHardware.HEADEND);rack.upperDevice=device(MediaHardware.PBX);rack.device.ports.getFirst().ip=lan+"10";rack.upperDevice.ports.getFirst().ip=lan+"11";
            var sw=place(level,base.offset(4,0,1),NetLab.SWITCH.get());var pc=place(level,base.offset(7,0,1),NetLab.LAPTOP.get());pc.device=new Device("pc");Hardware.initializeHost(pc.device,true);pc.device.ports.getFirst().ip=lan+"100";
            var a=place(level,base.offset(1,0,5),Media.DEVICES.get(MediaHardware.PHONE).get());var b=place(level,base.offset(4,0,5),Media.DEVICES.get(MediaHardware.PHONE).get());a.device.ports.getFirst().ip=lan+"20";b.device.ports.getFirst().ip=lan+"21";
            String password="Media"+UUID.randomUUID().toString().replace("-","").substring(0,12);for(var d:List.of(rack.device,rack.upperDevice)){var state=MediaState.get(d);state.owner=p.getUUID().toString();state.admin=ConfigStore.secret(password);state.save(d);}for(var h:List.of(a,b)){var s=MediaState.get(h.device);s.owner=p.getUUID().toString();s.server=lan+"11";s.number=h==a?"1001":"1002";s.password=password;s.save(h.device);var pbx=MediaState.get(rack.upperDevice);pbx.subscribers.put(s.number,ConfigStore.secret(password));pbx.save(rack.upperDevice);}
            var stb=place(level,base.offset(7,0,5),Media.DEVICES.get(MediaHardware.STB).get());stb.device.ports.getFirst().ip=lan+"30";var ss=MediaState.get(stb.device);ss.server=lan+"10";ss.channel=7;ss.owner=p.getUUID().toString();ss.save(stb.device);var tv=place(level,base.offset(9,0,5),Media.DEVICES.get(MediaHardware.TV).get());var splitter=place(level,base.offset(9,0,3),Media.DEVICES.get(MediaHardware.SPLITTER).get());var speaker=place(level,base.offset(11,0,3),Media.DEVICES.get(MediaHardware.SPEAKER).get());
            int i=0;wire(rack,0,sw,i++,"copper");wire(rack,128,sw,i++,"copper");for(var h:List.of(pc,a,b,stb))wire(h,0,sw,i++,"copper");wire(stb,2,tv,0,"hdmi");wire(tv,1,splitter,0,"audio");wire(splitter,1,speaker,0,"audio");
            PowerSystem.demo(level,rack,base.offset(1,0,3),base.offset(3,0,3),List.of(Map.entry(rack,0),Map.entry(rack,1),Map.entry(sw,0),Map.entry(a,0),Map.entry(b,0),Map.entry(stb,0),Map.entry(tv,0),Map.entry(splitter,0),Map.entry(speaker,0)));
            for(var host:List.of(rack,sw,pc,a,b,stb,tv,splitter,speaker)){MemoryCards.demo(host.device);if(host.upperDevice!=null)MemoryCards.demo(host.upperDevice);host.changed();}
            give(p,new ItemStack(NetLab.GUIDE.get()));give(p,new ItemStack(NetLab.PORTABLE_TERMINAL.get()));give(p,new ItemStack(NetLab.GOGGLES.get()));
            var book=new ItemStack(Items.WRITABLE_BOOK);book.set(net.minecraft.core.component.DataComponents.WRITABLE_BOOK_CONTENT,new net.minecraft.world.item.component.WritableBookContent(List.of(net.minecraft.server.network.Filterable.passThrough("NetLab Media\nАТС: "+lan+"11\nIPTV: "+lan+"10\nПароль: "+password+"\n\nТелефоны: 1001 и 1002. Открой каждый аппарат и звони. Для микрофона нужен Simple Voice Chat и UDP 24454. Два игрока — две трубки."),net.minecraft.server.network.Filterable.passThrough("IPTV: ноутбук → IPTV / АТС → IP "+lan+"10 и пароль с первой страницы. Создай канал 7, добавь ссылку и длительность, нажми «В эфир». Приставка уже настроена.\n\nВнешние видео требуют действующего Sputnik и маршрута медиасервера к интернет-шлюзу. В Console медиасервера: iptv gateway IP. Демостенд не создаёт спутниковый тракт."))));give(p,book);
            c.getSource().sendSuccess(()->Component.literal("Стенд Media готов. Номера 1001 / 1002; адреса и случайный пароль записаны в выданной книге. IPTV требует подключения внешнего интернет-шлюза Sputnik."),false);return 1;}))));}
    private static Device device(String kind){var d=new Device(kind);MediaHardware.initialize(d);return d;}
    private static DeviceEntity place(ServerLevel level,BlockPos pos,DeviceBlock block){level.setBlockAndUpdate(pos,block.defaultBlockState().setValue(DeviceBlock.FACING,Direction.NORTH));return (DeviceEntity)level.getBlockEntity(pos);}
    private static void wire(DeviceEntity a,int ap,DeviceEntity b,int bp,String kind){a.links.put(ap,new DeviceEntity.Peer(b.getBlockPos().asLong(),bp,kind.equals("audio")?0x222222:0x397edb,"",kind));b.links.put(bp,new DeviceEntity.Peer(a.getBlockPos().asLong(),ap,kind.equals("audio")?0x222222:0x397edb,"",kind));a.connectionChanged(ap);b.connectionChanged(bp);}
    private static void give(ServerPlayer p,ItemStack stack){if(!p.addItem(stack))p.drop(stack,false);}
}
